// Type constraints
[HttpGet("{id:int}")] // Only matches integers
public IActionResult GetById(int id) { }

[HttpGet("{name:alpha}")] // Only matches letters
public IActionResult GetByName(string name) { }

// Range constraint
[HttpGet("{id:int:min(1)}")] // Minimum value 1
public IActionResult GetById(int id) { }

// Regex constraint
[HttpGet("{id:regex(^\\d{{3}}$)}")] // Exactly 3 digits
public IActionResult GetByCode(string id) { }

// Optional parameter
[HttpGet("{id?}")] // Optional
public IActionResult Get(int? id) { }
